<?php

declare(strict_types=1);

namespace Sabri\CF03\Application;

use DateTimeImmutable;
use JsonException;
use Sabri\CF03\Contracts\QueryableFinancialRepository;
use Sabri\CF03\Support\InvariantViolation;
use Throwable;

final class DonationCheckoutService
{
    public function __construct(private readonly RuntimeConfiguration $configuration,private readonly DonationProviderRegistry $providers,private readonly QueryableFinancialRepository $repository){}
    /** @return array<string,mixed> */
    public function create(DonationIntentDraft $draft,string $providerCode):array
    {
        $this->configuration->assertDonationCheckoutReady();$draft->assertProviderCheckoutAvailable();if($providerCode!==$this->configuration->providerCode()){throw new InvariantViolation('Requested donation provider does not match the approved runtime provider.');}$requestHash=$this->requestHash($draft,$providerCode);$claimId='idem.'.substr(hash('sha256','donation-checkout|'.$draft->donorReference().'|'.$draft->idempotencyKey()),0,48);$existing=$this->repository->get('idempotency',$claimId);if($existing!==null){return $this->replay($existing,$requestHash);}$now=$draft->createdAt();$this->repository->insert('idempotency',$claimId,['scope'=>'donation_checkout','idempotency_key'=>$claimId,'actor_ref'=>$draft->donorReference(),'request_hash'=>$requestHash,'state'=>'pending','result_ref'=>null,'created_at'=>$now,'completed_at'=>null,'expires_at'=>$now->modify('+24 hours')]);
        try{$checkout=$this->providers->get($providerCode)->createHostedDonationCheckout($draft);if($checkout->providerCode()!==$providerCode){throw new InvariantViolation('Hosted checkout provider identity mismatch.');}$donationId=self::donationIdForIntent($draft->intentId());$consentId=$draft->monthly()?self::consentIdForIntent($draft->intentId()):null;$traceId='trace.'.substr(hash('sha256',$draft->intentId().'|'.$requestHash),0,40);$this->repository->transaction(function()use($draft,$providerCode,$checkout,$requestHash,$claimId,$donationId,$consentId,$traceId,$now):void{$this->repository->insert('intents',$draft->intentId(),['intent_id'=>$draft->intentId(),'actor_ref'=>$draft->donorReference(),'product_id'=>$draft->monthly()?'donation.monthly':'donation.one_time','price_version_id'=>null,'amount_minor'=>$draft->amount()->minorUnits(),'currency'=>$draft->amount()->currency(),'provider'=>$providerCode,'provider_ref'=>$checkout->providerSessionReference(),'state'=>'provider_pending','failure_code'=>null,'idempotency_key'=>$claimId,'request_hash'=>$requestHash,'expires_at'=>$checkout->expiresAt(),'record_version'=>1,'trace_id'=>$traceId,'created_at'=>$now,'updated_at'=>$now]);if($consentId!==null){$this->repository->insert('recurring_consents',$consentId,['consent_id'=>$consentId,'actor_ref'=>$draft->donorReference(),'product_id'=>'donation.monthly','amount_minor'=>$draft->amount()->minorUnits(),'currency'=>$draft->amount()->currency(),'interval_code'=>'month','next_charge_at'=>$now->modify('+1 month'),'terms_hash'=>hash('sha256','donation.monthly|'.$draft->amount()->minorUnits().'|'.$draft->amount()->currency()),'cancellation_path'=>'/billing/donations','state'=>'pending_provider','captured_at'=>$now,'revoked_at'=>null]);}$this->repository->insert('donations',$donationId,['donation_id'=>$donationId,'donor_ref'=>$draft->donorReference(),'amount_minor'=>$draft->amount()->minorUnits(),'currency'=>$draft->amount()->currency(),'purpose_code'=>'institutional_sustainability_and_homeopathy_advancement','recurring'=>$draft->monthly(),'recurring_consent_id'=>$consentId,'provider_ref'=>$checkout->providerSessionReference(),'receipt_ref'=>null,'state'=>'provider_pending','anonymous_public'=>true,'record_version'=>1,'created_at'=>$now,'updated_at'=>$now]);$updated=$this->repository->updateWhere('idempotency',['idempotency_key'=>$claimId,'state'=>'pending'],['state'=>'completed','result_ref'=>$draft->intentId(),'completed_at'=>$now]);if($updated!==1){throw new InvariantViolation('Donation checkout idempotency claim was not completed atomically.');}});return ['status'=>'provider_pending','intent_id'=>$draft->intentId(),'provider'=>$providerCode,'provider_session_reference'=>$checkout->providerSessionReference(),'hosted_url'=>$checkout->hostedUrl(),'expires_at'=>$checkout->expiresAt()->format(DATE_ATOM),'monthly'=>$draft->monthly(),'amount_minor'=>$draft->amount()->minorUnits(),'currency'=>$draft->amount()->currency(),'reused'=>false];}catch(Throwable $error){$this->repository->updateWhere('idempotency',['idempotency_key'=>$claimId,'state'=>'pending'],['state'=>'failed','completed_at'=>new DateTimeImmutable('now')]);throw $error;}
    }
    /** @return array<string,mixed> */ private function replay(array $claim,string $requestHash):array{if(($claim['request_hash']??null)!==$requestHash){throw new InvariantViolation('Donation idempotency key was reused with a different request.');}if(($claim['state']??null)!=='completed'||!is_string($claim['result_ref']??null)){throw new InvariantViolation('Donation checkout request is already in progress or previously failed.');}$intent=$this->repository->get('intents',$claim['result_ref']);if($intent===null){throw new InvariantViolation('Completed donation idempotency record has no canonical intent.');}$provider=$this->providers->get((string)$intent['provider']);$checkout=$provider->resumeHostedDonationCheckout((string)$intent['provider_ref']);return ['status'=>(string)($intent['state']??'provider_pending'),'intent_id'=>(string)$intent['intent_id'],'provider'=>(string)$intent['provider'],'provider_session_reference'=>$checkout->providerSessionReference(),'hosted_url'=>$checkout->hostedUrl(),'expires_at'=>$checkout->expiresAt()->format(DATE_ATOM),'monthly'=>((string)($intent['product_id']??''))==='donation.monthly','amount_minor'=>(int)$intent['amount_minor'],'currency'=>(string)$intent['currency'],'reused'=>true];}
    private function requestHash(DonationIntentDraft $draft,string $providerCode):string{try{return hash('sha256',json_encode(['actor'=>$draft->donorReference(),'provider'=>$providerCode,'payload'=>$draft->toSafePayload()],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES));}catch(JsonException $error){throw new InvariantViolation('Donation request could not be canonicalized.',0,$error);}}
    public static function donationIdForIntent(string $intentId):string{return 'donation.'.substr(hash('sha256',$intentId),0,40);}public static function consentIdForIntent(string $intentId):string{return 'consent.'.substr(hash('sha256',$intentId),0,40);}
}
